const story=document.querySelector('.robot-story'),boards=[...document.querySelectorAll('.board')];document.querySelector('#motion').dataset.height='1480';function fit(){const s=story.clientWidth/1920;boards.forEach(b=>{b.style.height=(+b.dataset.height*s)+'px';b.querySelector('.board-inner').style.transform=`scale(${s})`})}new ResizeObserver(fit).observe(story);fit();
const box=document.querySelector('#original-lightbox'),frame=document.querySelector('.original-motion-frame iframe'),motionButton=document.querySelector('[data-motion]');let last,ready=false,wantedPlay=location.hash==='#motion';function send(action,view){frame.contentWindow?.postMessage({type:'robot-original-motion-command',action,view},location.origin)}motionButton.textContent='播放环绕';motionButton.setAttribute('aria-pressed','false');
addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.type!=='robot-original-motion-state')return;const s=e.data;ready=s.ready;motionButton.textContent=s.playing?'暂停动效':s.view==='monitor'&&s.ended?'重播巡检':s.view==='monitor'?'播放巡检':'播放环绕';motionButton.setAttribute('aria-pressed',String(s.playing));document.querySelectorAll('[data-motion-view]').forEach(b=>b.classList.toggle('active',b.dataset.motionView===s.view));const status=document.querySelector('[data-motion-status]');if(status)status.textContent=s.view==='overview'?(s.hovered>=0?'悬停暂停 / 当前机器人与底座放大':s.playing?'顺时针环绕 / 悬停查看机器人':'已暂停，点击播放环绕'):s.ended?'5秒巡检演示已完成 / 可重播':s.playing?'橙色机器人沿轨道向前巡检':'已暂停';if(ready&&wantedPlay){wantedPlay=false;send('play')}});
frame.addEventListener('load',()=>send('state'));addEventListener('hashchange',()=>{if(location.hash==='#motion'){if(ready)send('play');else wantedPlay=true}});document.addEventListener('click',e=>{const image=e.target.closest('[data-image]');if(image){last=image;box.querySelector('img').src=image.dataset.image;box.showModal();return}if(e.target.closest('[data-zoom]')){document.body.classList.toggle('expanded');fit()}const choice=e.target.closest('[data-motion-view]');if(choice){send('view',choice.dataset.motionView);return}if(e.target.closest('[data-motion]')){if(ready)send('toggle');else{wantedPlay=true;motionButton.textContent='正在载入动效…'}}if(e.target.closest('a[href="#motion"]')){if(ready)send('play');else wantedPlay=true}});box.querySelector('.close').addEventListener('click',()=>box.close());box.addEventListener('click',e=>{if(e.target===box)box.close()});box.addEventListener('close',()=>last?.focus());
